import {CATALOG,PACKS,INITIAL,signature} from './engine.mjs';
const $=s=>document.querySelector(s),storageKey='gleiswerk.inventory.v1',savedKey='gleiswerk.favorites.v1';
const meta=Object.fromEntries(CATALOG.map(a=>[a[0],a]));
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=name=>`<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const fmt=n=>new Intl.NumberFormat('de-CH',{maximumFractionDigits:1}).format(n);
let inventory={...INITIAL},favorites=new Set(),results=[],lastSearch=null,selected=null,mode='stock',worker=null,debounce=null,pageLimit=12,zoom=1,pan={x:0,y:0},drag=null,savedOnly=false,partsOpen=false,toastTimer;
let storageAvailable=true;
try{const raw=localStorage.getItem(storageKey);if(raw)inventory=normalize(JSON.parse(raw));const saved=JSON.parse(localStorage.getItem(savedKey)||'[]');if(Array.isArray(saved))favorites=new Set(saved.filter(x=>typeof x==='string').slice(0,500));}catch{storageAvailable=false;}
function normalize(raw){const obj=raw.inventory||raw;if(!obj||typeof obj!=='object'||Array.isArray(obj))throw new Error('Die Datei enthält keinen Gleisbestand.');const out=Object.fromEntries(CATALOG.map(([id])=>[id,0]));let recognized=0;for(const [id,n]of Object.entries(obj)){if(!(id in out))throw new Error(`Gleisart „${id}“ wird noch nicht unterstützt.`);if(typeof n!=='number'||!Number.isFinite(n)||n<0||!Number.isInteger(n)||n>200)throw new Error(`Ungültige Stückzahl bei ${id}. Erlaubt sind ganze Zahlen von 0 bis 200.`);out[id]=n;recognized++;}if(!recognized)throw new Error('Die Datei enthält keine unterstützten Gleisarten.');return out;}
function persist(){try{localStorage.setItem(storageKey,JSON.stringify(inventory));localStorage.setItem(savedKey,JSON.stringify([...favorites].slice(0,500)));}catch{storageAvailable=false;}if(!storageAvailable){$('.local-status').textContent='Speicherung nicht verfügbar';}}
function toast(s){clearTimeout(toastTimer);$('#toast').textContent=s;$('#toast').classList.add('visible');toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function trackIcon(id){let d='M4 12h22';if(['24130','24230','24224'].includes(id))d='M5 25A20 20 0 0 1 25 5';if(['24611','24612'].includes(id))d='M3 21h24M3 21c12 0 10-12 24-12';if(['24671','24672'].includes(id))d='M4 26A22 22 0 0 1 26 4M4 26C7 14 20 14 26 12';if(id==='24620')d='M3 10h24M4 23 26 4';if(id==='24977')d='M3 16h21m0-8v16';if(id==='basis')d='M3 18h24M10 18V9h10v9';return `<svg viewBox="0 0 30 30" aria-hidden="true"><path d="${d}"/></svg>`;}
function renderInventory(){
 $('#starter-presets').innerHTML=['farm','city'].map(key=>{const p=PACKS[key];return `<button class="preset" data-preset="${key}" title="Startset ${p.article} zum Bestand hinzufügen"><span class="preset-name">${icon('plus')}${p.name}</span><small>${p.article} · 21 Gleise</small></button>`;}).join('');
 $('#expansion-presets').innerHTML=['C1','C2','C3','C4','C5'].map(key=>`<button data-preset="${key}" title="${key} · ${PACKS[key].article} hinzufügen">+ ${key}</button>`).join('');
 $('#inventory-rows').innerHTML=['Geraden','Bögen','Weichen & Abschlüsse'].map(group=>`<section class="inventory-group"><div class="group-heading">${escape(group)}</div>${CATALOG.filter(a=>a[3]===group).map(([id,name,geometry])=>`<div class="inventory-row"><span class="track-icon">${trackIcon(id)}</span><span class="track-info"><label class="track-code" for="qty-${id}">${id==='basis'?'Basisstation':id}</label><span class="track-description" title="${name} · ${geometry}">${id==='basis'?geometry:name}</span></span><div class="stepper"><button data-step="-1" data-part="${id}" aria-label="${escape(name)} ${id} verringern">−</button><input id="qty-${id}" type="number" inputmode="numeric" min="0" max="200" value="${inventory[id]||0}" data-part="${id}" aria-label="Stückzahl ${id==='basis'?'Basisstation':id}"><button data-step="1" data-part="${id}" aria-label="${escape(name)} ${id} erhöhen">+</button></div></div>`).join('')}</section>`).join('');updateStats();
}
function updateStats(){const total=Object.values(inventory).reduce((a,b)=>a+b,0),types=Object.values(inventory).filter(n=>n>0).length;$('#inventory-badge').textContent=total;$('#stat-pieces').textContent=total;$('#stat-types').textContent=types;$('#saved-count').textContent=favorites.size;}
function setInventory(next,message){inventory=normalize(next);persist();renderInventory();scheduleSearch();if(message)toast(message);}
function scheduleSearch(){clearTimeout(debounce);$('#search-message').innerHTML='<span class="status-dot"></span>Bestand geändert · Suche wird aktualisiert …';debounce=setTimeout(runSearch,350);}
function runSearch(){clearTimeout(debounce);if(worker)worker.terminate();const keep=selected?.key;const opts={mode,maxPieces:Number($('#max-pieces').value),maxResults:240};$('#search-button').disabled=true;$('#search-message').className='search-message searching';$('#search-message').innerHTML='<span class="status-dot"></span>Gleise kombinieren und Anschlüsse prüfen …';
 try{worker=new Worker(new URL('./worker.mjs',import.meta.url),{type:'module'});}catch(error){showSearchError(error.message);return;}
 worker.onmessage=({data})=>{if(data.type==='progress'){$('#search-message').innerHTML=`<span class="status-dot"></span>${data.found} Varianten berechnet …`;return;}if(data.type==='error'){showSearchError(data.message);return;}if(data.type==='done'){
  results=data.results.map(p=>({...p,key:signature(p)}));lastSearch=data;pageLimit=12;selected=results.find(p=>p.key===keep)||null;$('#stat-results').textContent=results.length;$('.stats-row>div:nth-child(3)>span:last-child').textContent=mode==='extra'?'Varianten mit Zukauf':'passende Strecken';$('#search-button').disabled=false;$('#search-message').className='search-message'+(data.limited?' warning':'');
  const text=data.limited?`${results.length} Treffer · Ergebnisgrenze erreicht. Filter eingrenzen oder Suchumfang anpassen.`:`${results.length} ${mode==='stock'?'passende Varianten':'Varianten mit Ergänzung'} · ${data.examined} Kandidaten geprüft · bis ${data.maxPieces} Gleisstücke.`;
  $('#search-message').innerHTML='<span class="status-dot"></span>'+escape(text);renderResults();worker.terminate();worker=null;
 }};worker.onerror=e=>{showSearchError(e.message||'Der Suchprozess konnte nicht geladen werden.');};worker.postMessage({inventory:{...inventory},options:opts});}
function showSearchError(message){if(worker)worker.terminate();worker=null;$('#search-button').disabled=false;$('#search-message').className='search-message warning';$('#search-message').textContent='Suche fehlgeschlagen. '+message;toast('Die Suche konnte nicht abgeschlossen werden. Bitte erneut versuchen.');}
function visibleResults(){const fam=$('#family-filter').value,w=Number($('#max-width').value)||Infinity,h=Number($('#max-height').value)||Infinity,sort=$('#sort').value;let plans=results.filter(p=>(fam==='all'||p.family===fam)&&(!savedOnly||favorites.has(p.key))&&((p.width<=w&&p.height<=h)||(p.height<=w&&p.width<=h)));
 const orders={play:(a,b)=>a.missingTotal-b.missingTotal||b.sidings-a.sidings||b.total-a.total,use:(a,b)=>b.total-a.total||a.missingTotal-b.missingTotal,compact:(a,b)=>a.width*a.height-b.width*b.height,missing:(a,b)=>a.missingTotal-b.missingTotal||b.total-a.total};return plans.sort(orders[sort]||orders.play);}
function renderResults(){const plans=visibleResults();$('#result-count').textContent=plans.length;$('#saved-filter').setAttribute('aria-pressed',String(savedOnly));$('#saved-count').textContent=favorites.size;$('#result-scope').textContent=lastSearch?.limited?'Begrenzte Trefferliste':'Innerhalb des Suchumfangs';$('#show-more').hidden=plans.length<=pageLimit;$('#empty-state').hidden=plans.length>0;$('#selected-view').hidden=!plans.length;
 if(!plans.length){selected=null;$('#results').innerHTML='';const hasStock=Object.values(inventory).some(Boolean),filtered=results.length>0;
  $('#empty-title').textContent=savedOnly?'Hier ist noch keine Strecke gemerkt':filtered?'Keine Strecke für diese Filter':hasStock?'Noch kein passender Aufbau gefunden':'Dein erstes Gleis wartet schon';
  $('#empty-copy').textContent=savedOnly?'Merke dir Strecken über das Herz. Die Merkliste gilt für den aktuellen Bestand und Suchmodus.':filtered?'Vergrößere die verfügbare Fläche oder wähle eine andere Streckenart.':hasStock?'Innerhalb der unterstützten Familien ist kein Aufbau möglich. Unter „Mit Ergänzung“ siehst du fehlende Gleise. Das schließt andere Gleisnetze nicht aus.':'Füge ein Startset hinzu oder gib deine Gleise einzeln ein.';
  $('#empty-action').textContent=savedOnly?'Alle Treffer anzeigen':filtered?'Filter zurücksetzen':hasStock?'Ergänzungen ansehen':'Beispielbestand laden';$('#empty-action').dataset.action=savedOnly?'all':filtered?'filters':hasStock?'extra':'example';return;
 }
 if(!selected||!plans.some(p=>p.key===selected.key)){selected=plans[0];zoom=1;pan={x:0,y:0};}
 $('#results').innerHTML=plans.slice(0,pageLimit).map(p=>{const active=p.key===selected.key;return `<article class="result-card${active?' selected':''}"><button class="result-select" data-select="${p.id}" aria-label="${escape(p.name)} anzeigen" aria-pressed="${active}"><div class="card-preview">${active?`<span class="selected-tag">${icon('check')}Ausgewählt</span>`:''}${svgPlan(p,true)}</div><div class="card-body"><span class="card-family">${p.family}</span><h3>${p.name}</h3><div class="card-meta"><span>${Math.ceil(p.width)} × ${Math.ceil(p.height)} cm</span><span>${p.total} Gleise</span></div>${p.missingTotal?`<div class="card-extra">+ ${p.missingTotal} Gleise fehlen</div>`:''}</div></button><button class="icon-button card-favorite" data-favorite="${p.id}" aria-label="${escape(p.name)} ${favorites.has(p.key)?'aus Merkliste entfernen':'merken'}" aria-pressed="${favorites.has(p.key)}">${icon('heart')}</button></article>`;}).join('');renderSelected();}
function pathD(points){return points.map((p,i)=>(i?'L':'M')+p.x.toFixed(3)+','+(-p.y).toFixed(3)).join(' ');}
function svgPlan(p,mini=false,download=false){const b=p.bounds,pad=mini?55:130,w=b.maxX-b.minX,h=b.maxY-b.minY;const vb=[b.minX-pad,-b.maxY-pad,w+2*pad,h+2*pad];let road='',rails='',ends='',labels='',used={};
 for(const item of p.pieces){used[item.part]=(used[item.part]||0)+1;const absent=used[item.part]>(inventory[item.part]||0),color=absent?'#c28b45':'#386654';for(const line of item.paths){const d=pathD(line);road+=`<path d="${d}" stroke="${absent?'#efe2cc':'#dfe6d9'}" stroke-width="34" fill="none" stroke-linejoin="round"/>`;rails+=`<path d="${d}" stroke="${color}" stroke-width="${mini?10:12}" fill="none" stroke-linejoin="round"/><path d="${d}" stroke="#fcfdf9" stroke-width="3" fill="none" stroke-linejoin="round"/>`;}
  for(const port of item.ports){const nx=-Math.sin(port.a)*17,ny=Math.cos(port.a)*17;ends+=`<path d="M${port.x+nx},${-port.y-ny}L${port.x-nx},${-port.y+ny}" stroke="#fcfdf9" stroke-width="3"/>`;}
  if(item.buffer){const port=item.ports[1],nx=-Math.sin(port.a)*22,ny=Math.cos(port.a)*22;ends+=`<path d="M${port.x+nx},${-port.y-ny}L${port.x-nx},${-port.y+ny}" stroke="#a4734e" stroke-width="8"/>`;}
  if(!mini&&($('#track-numbers').checked||download)){const line=item.paths[0],m=line[Math.floor((line.length-1)/2)];let mid=m,angle=0;if(line.length===2){mid={x:(line[0].x+line[1].x)/2,y:(line[0].y+line[1].y)/2};angle=-Math.atan2(line[1].y-line[0].y,line[1].x-line[0].x)/D;}else{const next=line[Math.min(line.length-1,Math.floor(line.length/2)+1)];angle=-Math.atan2(next.y-m.y,next.x-m.x)/D;}if(angle>90)angle-=180;if(angle< -90)angle+=180;
   labels+=`<text x="${mid.x}" y="${-mid.y-22}" transform="rotate(${angle} ${mid.x} ${-mid.y-22})" text-anchor="middle" font-family="Arial,sans-serif" font-size="20" font-weight="600" fill="${color}" stroke="#fcfdf9" stroke-width="3" paint-order="stroke">${item.part==='basis'?'Basis':item.part}</text>`;
  }
 }
 const transform=!mini&&!download?`translate(${pan.x} ${pan.y}) translate(${(b.minX+b.maxX)/2} ${-(b.minY+b.maxY)/2}) scale(${zoom}) translate(${-(b.minX+b.maxX)/2} ${(b.minY+b.maxY)/2})`:'';
 return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="${vb.join(' ')}" role="img" aria-label="${escape(p.name)} · ${Math.ceil(p.width)} mal ${Math.ceil(p.height)} Zentimeter"${download?' width="1600" height="1000"':''}><title>${escape(p.name)}</title><desc>Gleisplan aus ${p.total} Teilen. ${p.missingTotal?`${p.missingTotal} Teile fehlen im Bestand.`:'Alle Teile im Bestand.'} Artikelnummern und Stückliste in Gleiswerk.</desc>${download?`<rect x="${vb[0]}" y="${vb[1]}" width="${vb[2]}" height="${vb[3]}" fill="#fcfdf9"/>`:''}<g transform="${transform}">${road}${rails}${ends}${labels}</g></svg>`;
}
const D=Math.PI/180;
function renderSelected(){if(!selected)return;$('#selected-family').textContent=selected.family.toUpperCase();$('#selected-name').textContent=selected.name;$('#large-plan').innerHTML=svgPlan(selected);$('#zoom-label').textContent=Math.round(zoom*100)+' %';$('#canvas-dimensions').textContent=`ca. ${Math.ceil(selected.width)} × ${Math.ceil(selected.height)} cm`;
 $('#favorite-selected').setAttribute('aria-pressed',String(favorites.has(selected.key)));$('#favorite-selected').setAttribute('aria-label',favorites.has(selected.key)?'Strecke aus Merkliste entfernen':'Strecke merken');
 const chips=[`<span class="chip${selected.missingTotal?' gold':''}">${icon(selected.missingTotal?'plus':'check')}${selected.missingTotal?selected.missingTotal+' Gleise fehlen':'Alles im Bestand'}</span>`,`<span class="chip neutral">${selected.total} Gleisstücke</span>`,`<span class="chip neutral">${Math.min(100,Math.round(selected.utilization*100))} % Bestand genutzt</span>`];if(selected.sidings)chips.push(`<span class="chip neutral">${selected.sidings} Stumpfgleis${selected.sidings===1?'':'e'}</span>`);$('#plan-chips').innerHTML=chips.join('');renderParts();}
function renderParts(){if(!selected)return;$('#parts-panel').hidden=!partsOpen;$('#show-parts').setAttribute('aria-expanded',String(partsOpen));const totalStock=Object.values(inventory).reduce((a,b)=>a+b,0),usedStock=Object.entries(selected.used).reduce((a,[id,n])=>a+Math.min(n,inventory[id]||0),0);
 const relevant=CATALOG.filter(([id])=>(selected.used[id]||0)||(inventory[id]||0));$('#parts-panel').innerHTML=`<div class="parts-intro"><strong>Was du für diesen Plan brauchst</strong><small>${totalStock-usedStock} Gleisstücke bleiben übrig</small></div><table><thead><tr><th>Artikel</th><th>Gleisart</th><th>Benötigt</th><th>Bestand</th><th>${selected.missingTotal?'Fehlt':'Übrig'}</th></tr></thead><tbody>${relevant.map(([id,name])=>{const n=selected.used[id]||0,stock=inventory[id]||0,missing=Math.max(0,n-stock);return `<tr class="${missing?'missing':''}" data-highlight="${id}"><td>${id==='basis'?'Basis':id}</td><td>${name}</td><td>${n}</td><td>${stock}</td><td>${selected.missingTotal?missing:Math.max(0,stock-n)}</td></tr>`;}).join('')}</tbody></table><p class="plan-note">${selected.note?escape(selected.note)+'<br>':''}Gleisfläche: ${fmt(selected.width)} × ${fmt(selected.height)} cm ohne Rand. Größter berechneter Anschlussrest: ${fmt(selected.validation.maxError)} mm. ${selected.used.basis?'Basisstation berücksichtigt.':'Separate Einspeisung erforderlich; im Plan ist keine Basisstation enthalten.'} ${selected.missingTotal?'Ocker markiert Stücke, die über deinen Bestand hinausgehen.':''}</p>`;
}
function favorite(p){if(favorites.has(p.key))favorites.delete(p.key);else favorites.add(p.key);persist();renderResults();}
function zoomTo(n){zoom=Math.max(.5,Math.min(4,n));renderSelected();}
function downloadFile(name,content,type){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function openDialog(kind){const help=`<span class="eyebrow">WILLKOMMEN IN GLEISWERK</span><h2>Aus Gleisen werden<br>Spielmöglichkeiten.</h2><ol><li><strong>Bestand erfassen.</strong> Startsets oder C1–C5 hinzufügen und einzelne Mengen anpassen. Wiederholtes Klicken addiert ein Set.</li><li><strong>Strecken entdecken.</strong> Die Suche startet automatisch. Wähle Streckenart, Fläche und Sortierung. „Mit Ergänzung“ zeigt Vorschläge mit höchstens 16 fehlenden Gleisen.</li><li><strong>Plan mitnehmen.</strong> Zoome in die Zeichnung, schalte Artikelnummern ein und öffne die Stückliste. Über SVG erhältst du einen skalierbaren Plan zum Speichern oder Drucken.</li></ol><p class="dialog-note">Dein Bestand und deine Merkliste werden nur in diesem Browser gespeichert. Exportiere den Bestand als JSON, um ihn auf einem anderen Gerät zu importieren. Die Suche ist auf die beschriebenen Streckenfamilien begrenzt.</p>`;
 const sources=`<span class="eyebrow">NACHVOLLZIEHBARE GEOMETRIE</span><h2>Grundlagen & Quellen</h2><p>Gleiswerk ist ein unabhängiges Planungswerkzeug für Märklin C-Gleis in H0, kein offizielles Angebot von Märklin.</p><ul><li><a href="https://www.marklin.com/products/details/article/29653" target="_blank" rel="noopener noreferrer">Startset Landwirtschaft · 29653</a></li><li><a href="https://www.marklin.com/products/details/article/29296" target="_blank" rel="noopener noreferrer">Startset Kommunaldienst · 29296</a></li><li><a href="https://www.marklin.com/products/details/article/24900" target="_blank" rel="noopener noreferrer">Ergänzung C1 · 24900</a>, <a href="https://www.marklin.com/products/details/article/24902" target="_blank" rel="noopener noreferrer">C2</a>, <a href="https://www.marklin.com/products/details/article/24903" target="_blank" rel="noopener noreferrer">C3</a>, <a href="https://www.marklin.com/products/details/article/24904" target="_blank" rel="noopener noreferrer">C4</a>, <a href="https://www.marklin.com/products/details/article/24905" target="_blank" rel="noopener noreferrer">C5</a></li><li><a href="https://www.jrline.sk/Images/64/MA24905.pdf" target="_blank" rel="noopener noreferrer">Märklin-Anleitung und Gleisplanbroschüre im Händlerarchiv (PDF)</a> · C4/C5: PDF-Seite 37, gedruckte Seite 12.</li><li><a href="https://modellbahning.de/maerklin-c-gleis-geometrie/" target="_blank" rel="noopener noreferrer">Geometrie der Bogenweichen 24671/24672</a></li></ul><p class="dialog-note">Nominalmaße: R1 = 360 mm, R2 = 437,5 mm; Bögen 30°, Gegenbögen 24,3°. Herstellerwerte sind gerundet. Die Darstellung ersetzt keinen Probeaufbau und keine Prüfung des Fahrzeugüberhangs. Der vollständige Suchumfang steht am Seitenende.</p>`;
 $('#info-content').innerHTML=kind==='sources'?sources:help;$('#info-dialog').showModal();}
function openInventory(open){$('#inventory-panel').classList.toggle('open',open);$('#inventory-open').setAttribute('aria-expanded',String(open));$('#drawer-backdrop').hidden=!open;if(open)$('#inventory-close').focus();else $('#inventory-open').focus();}

$('#inventory-panel').addEventListener('click',e=>{const preset=e.target.closest('[data-preset]');if(preset){const pack=PACKS[preset.dataset.preset],next={...inventory};for(const [id,n]of Object.entries(pack.parts)){if((next[id]||0)+n>200){toast('Maximal 200 Stück pro Gleisart.');return;}next[id]=(next[id]||0)+n;}setInventory(next,`${pack.name} · ${pack.article} hinzugefügt`);return;}const step=e.target.closest('[data-step]');if(step){const id=step.dataset.part,n=Math.max(0,Math.min(200,(inventory[id]||0)+Number(step.dataset.step)));inventory[id]=n;$(`#qty-${id}`).value=n;updateStats();persist();scheduleSearch();}});
$('#inventory-rows').addEventListener('input',e=>{const field=e.target;if(!field.matches('input[data-part]'))return;const n=Number(field.value);if(!Number.isInteger(n)||n<0||n>200){field.setCustomValidity('Bitte eine ganze Zahl zwischen 0 und 200 eingeben.');field.reportValidity();return;}field.setCustomValidity('');inventory[field.dataset.part]=n;persist();updateStats();scheduleSearch();});
$('#inventory-rows').addEventListener('change',e=>{if(e.target.matches('input[data-part]')&&!e.target.checkValidity())e.target.value=inventory[e.target.dataset.part]||0;});
$('#clear-stock').addEventListener('click',()=>setInventory(Object.fromEntries(CATALOG.map(([id])=>[id,0])),'Bestand geleert. Über das Beispiel kannst du ihn wieder laden.'));
$('#example-stock').addEventListener('click',()=>setInventory(INITIAL,'Beide Startsets geladen'));
$('#export-stock').addEventListener('click',()=>{downloadFile('gleiswerk-bestand.json',JSON.stringify({version:1,system:'maerklin-c',inventory},null,2),'application/json');toast('Bestand als JSON exportiert');});
$('#import-stock').addEventListener('click',()=>$('#import-file').click());$('#import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw new Error('Die Bestandsdatei ist zu groß (max. 100 KB).');setInventory(normalize(JSON.parse(await file.text())),'Bestand importiert');}catch(error){toast(error instanceof SyntaxError?'Die Datei ist kein gültiges JSON.':error.message);}e.target.value='';});
$('#search-button').addEventListener('click',runSearch);document.querySelectorAll('[data-mode]').forEach(button=>button.addEventListener('click',()=>{mode=button.dataset.mode;document.querySelectorAll('[data-mode]').forEach(b=>b.setAttribute('aria-selected',String(b===button)));selected=null;runSearch();}));
for(const id of ['family-filter','sort','max-width','max-height'])$('#'+id).addEventListener(id.startsWith('max-')?'input':'change',()=>{pageLimit=12;renderResults();});$('#max-pieces').addEventListener('change',runSearch);
$('#clear-area').addEventListener('click',()=>{$('#max-width').value='';$('#max-height').value='';renderResults();});
$('#saved-filter').addEventListener('click',()=>{savedOnly=!savedOnly;renderResults();});$('#favorite-selected').addEventListener('click',()=>{if(selected)favorite(selected);});
$('#results').addEventListener('click',e=>{const fav=e.target.closest('[data-favorite]');if(fav){const p=results.find(x=>x.id===fav.dataset.favorite);if(p)favorite(p);return;}const b=e.target.closest('[data-select]');if(b){selected=results.find(p=>p.id===b.dataset.select);zoom=1;pan={x:0,y:0};renderResults();if(innerWidth<570)$('#selected-view').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}});
$('#show-more').addEventListener('click',()=>{pageLimit+=12;renderResults();});$('#show-parts').addEventListener('click',()=>{partsOpen=!partsOpen;renderParts();});$('#track-numbers').addEventListener('change',renderSelected);
$('#export-plan').addEventListener('click',()=>{if(!selected)return;downloadFile('gleiswerk-'+selected.name.toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.svg',svgPlan(selected,false,true),'image/svg+xml');toast('Gleisplan mit Artikelnummern als SVG exportiert');});
$('#zoom-in').addEventListener('click',()=>zoomTo(zoom+.25));$('#zoom-out').addEventListener('click',()=>zoomTo(zoom-.25));$('#zoom-fit').addEventListener('click',()=>{pan={x:0,y:0};zoomTo(1);});
$('#large-plan').addEventListener('pointerdown',e=>{if(!selected)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,pan:{...pan}};e.currentTarget.setPointerCapture(e.pointerId);});$('#large-plan').addEventListener('pointermove',e=>{if(!drag||!selected)return;const rect=$('#large-plan').getBoundingClientRect(),scale=Math.max((selected.bounds.maxX-selected.bounds.minX+260)/rect.width,(selected.bounds.maxY-selected.bounds.minY+260)/rect.height);pan={x:drag.pan.x+(e.clientX-drag.x)*scale,y:drag.pan.y+(e.clientY-drag.y)*scale};$('#large-plan').innerHTML=svgPlan(selected);});for(const name of ['pointerup','pointercancel'])$('#large-plan').addEventListener(name,()=>drag=null);
$('#empty-action').addEventListener('click',()=>{const a=$('#empty-action').dataset.action;if(a==='all'){savedOnly=false;renderResults();}else if(a==='filters'){$('#family-filter').value='all';$('#max-width').value='';$('#max-height').value='';renderResults();}else if(a==='extra')$('#tab-extra').click();else setInventory(INITIAL,'Beide Startsets geladen');});
$('#inventory-open').addEventListener('click',()=>openInventory(true));$('#inventory-close').addEventListener('click',()=>openInventory(false));$('#drawer-backdrop').addEventListener('click',()=>openInventory(false));document.addEventListener('keydown',e=>{if(e.key==='Escape'&&$('#inventory-panel').classList.contains('open'))openInventory(false);});
$('#help-open').addEventListener('click',()=>openDialog('help'));$('#sources-open').addEventListener('click',()=>openDialog('sources'));$('#info-close').addEventListener('click',()=>$('#info-dialog').close());$('#info-dialog').addEventListener('click',e=>{if(e.target===$('#info-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
// Arrow-key navigation follows the tab pattern; only the selected tab is tabbable.
function syncTabIndex(){document.querySelectorAll('[data-mode]').forEach(b=>b.tabIndex=b.getAttribute('aria-selected')==='true'?0:-1);}document.querySelector('.tabs').addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const b=e.key==='Home'||e.key==='ArrowLeft'?$('#tab-stock'):$('#tab-extra');b.click();b.focus();syncTabIndex();}});document.querySelectorAll('[data-mode]').forEach(b=>b.addEventListener('click',syncTabIndex));
renderInventory();syncTabIndex();if(!storageAvailable)persist();runSearch();
